"""Doc 6 Benchmark QA items (TERRA_QA_081 - TERRA_QA_086)"""

DOC6_ITEMS = [{'id': 'TERRA_QA_081', 'source_document': 'a3515bb7de4f407c999b38eaad2be279.md', 'category': 'risk_assessment_mapping', 'sub_category': 'Đặc điểm địa hình và khí hậu miền Trung', 'difficulty': 'medium', 'question': 'Địa hình và khí hậu dải đất miền Trung có những đặc điểm tự nhiên nổi bật nào ảnh hưởng trực tiếp đến chế độ thiên tai mưa bão?', 'ground_truth_context': 'Miền Trung, dải đất hẹp trải dài trên 10 vĩ độ, gồm 18 tỉnh từ Thanh Hóa đến Bình Thuận với trên 1.000 km bờ biển. Phần lớn diện tích nằm ở sườn phía đông dốc đứng của dãy Trường Sơn, đồng bằng ven biển bị chia cắt thành nhiều đoạn ngắn bởi những dãy núi ngang, nhô ra sát biển (đèo Ngang, Hải Vân, Cù Mông, Cả...) và Tây Nguyên có độ cao phổ biến trên 1.000 m. Địa hình rất phức tạp, bị chia cắt mạnh.\n\nKhí hậu miền Trung bị phân hoá mạnh và có những nét độc đáo, khác biệt nhau ở mỗi khu vực ngay khi chịu tác động của cùng một hình thế thời tiết. Nổi bật là sự dịch chuyển mùa mưa bão lũ theo không gian. Mùa mưa bão lũ thường bắt đầu từ tháng VII và kết thúc vào tháng XI, tháng XII với tần suất hoạt động của bão lớn nhất trong cả nước.', 'ground_truth_answer': 'Miền Trung là dải đất hẹp trải dài trên 10 vĩ độ gồm 18 tỉnh từ Thanh Hóa đến Bình Thuận với hơn 1.000 km bờ biển. Phần lớn diện tích nằm ở sườn phía đông dốc đứng của dãy Trường Sơn, đồng bằng ven biển bị chia cắt thành nhiều đoạn ngắn bởi các dãy núi ngang nhô ra sát biển (đèo Ngang, Hải Vân, Cù Mông, Cả...) và Tây Nguyên có độ cao phổ biến trên 1.000 m. Địa hình rất phức tạp, bị chia cắt mạnh. Khí hậu phân hóa mạnh và có nét độc đáo khác biệt ở mỗi khu vực, nổi bật là sự dịch chuyển mùa mưa bão lũ theo không gian (thường bắt đầu từ tháng VII và kết thúc vào tháng XI, tháng XII với tần suất bão lớn nhất cả nước).', 'keywords': ['địa hình', 'khí hậu', 'Trường Sơn', 'miền Trung', 'phân hóa', 'mùa bão lũ']}, {'id': 'TERRA_QA_082', 'source_document': 'a3515bb7de4f407c999b38eaad2be279.md', 'category': 'typhoon_flood', 'sub_category': 'Mạng lưới sông ngòi và nguy cơ lũ quét miền Trung', 'difficulty': 'medium', 'question': 'Đặc điểm mạng lưới sông ngòi miền Trung như thế nào và tại sao khu vực này lại có tần suất cao về lũ lớn và lũ quét khốc liệt?', 'ground_truth_context': 'Miền Trung có trên 740 sông với chiều dài mỗi sông trên 10 km, trong đó có 26 sông với diện tích lưu vực trên 500 km². Mạng lưới sông khá dày. Đa số các lưu vực sông đều nhỏ, 4 hệ thống sông lớn là sông Mã, Cả, Thu Bồn, Ba. Sông thường ngắn, rất dốc, rừng đầu nguồn bị huỷ hoại nặng, khả năng điều tiết dòng chảy kém, nên miền Trung là nơi có tần suất cao về lũ lớn, lũ quét với sức tàn phá ghê gớm.\n\nThiên tai mưa, bão, lũ thường xảy ra, ít nhất cũng ở một vài tỉnh, nhiều nhất có thể xảy ra trên toàn miền như năm 1964, 1970, 1975, 1985, 1996. Thủy tai tại miền Trung xảy ra ngày càng thường xuyên hơn, trầm trọng hơn, thiệt hại ngày càng lớn hơn.', 'ground_truth_answer': 'Miền Trung có mạng lưới sông khá dày với trên 740 sông dài trên 10 km (trong đó có 26 sông có diện tích lưu vực trên 500 km² và 4 hệ thống sông lớn là sông Mã, Cả, Thu Bồn, Ba). Đa số các lưu vực sông đều nhỏ, sông ngắn và rất dốc, kết hợp với rừng đầu nguồn bị hủy hoại nặng dẫn đến khả năng điều tiết dòng chảy kém. Do đó, miền Trung có tần suất cao về lũ lớn và lũ quét với sức tàn phá dữ dội, đồng thời thủy tai xảy ra ngày càng thường xuyên và trầm trọng hơn.', 'keywords': ['sông ngòi', 'miền Trung', 'sông dốc', 'lũ lớn', 'lũ quét', 'rừng đầu nguồn']}, {'id': 'TERRA_QA_083', 'source_document': 'a3515bb7de4f407c999b38eaad2be279.md', 'category': 'typhoon_flood', 'sub_category': 'Thống kê tần suất và phân bố bão lũ miền Trung', 'difficulty': 'hard', 'question': 'Theo số liệu thống kê, tỷ lệ bão và áp thấp nhiệt đới ảnh hưởng đến miền Trung chiếm bao nhiêu phần trăm cả nước và phân bố giữa các khu vực ra sao?', 'ground_truth_context': 'Theo số liệu thống kê nhiều năm, miền Trung là khu vực chịu ảnh hưởng nhiều nhất của bão và áp thấp nhiệt đới, chiếm tới 65% số bão ảnh hưởng đến Việt Nam. Trung bình hàng năm có 4 cơn bão và 4 ATNĐ ảnh hưởng đến khu vực miền Trung. Phân bố số cơn bão đổ bộ hàng năm vào các khu vực ở miền Trung như sau:\n\n| Khu vực | Tỷ lệ |\n| :-------------------------------- | :---- |\n| Từ Thanh Hoá đến Hà Tĩnh         | 31,1% |\n| Từ Quảng Bình đến Thừa Thiên - Huế | 26,2% |\n| Từ Đà Nẵng đến Bình Định         | 20,4% |\n| Từ Phú Yên đến Bình Thuận        | 22,3% |\n\nKhu vực Thanh Hóa đến Thừa Thiên - Huế bị ảnh hưởng nhiều nhất của bão (57,3%).', 'ground_truth_answer': 'Theo thống kê nhiều năm, miền Trung là khu vực chịu ảnh hưởng nhiều nhất của bão và áp thấp nhiệt đới (ATNĐ), chiếm tới 65% số bão ảnh hưởng đến Việt Nam (trung bình hàng năm có 4 cơn bão và 4 ATNĐ). Phân bố bão đổ bộ hàng năm gồm: Thanh Hoá đến Hà Tĩnh chiếm 31,1%; Quảng Bình đến Thừa Thiên - Huế chiếm 26,2%; Đà Nẵng đến Bình Định chiếm 20,4%; Phú Yên đến Bình Thuận chiếm 22,3%. Trong đó khu vực từ Thanh Hóa đến Thừa Thiên - Huế chịu ảnh hưởng nhiều nhất với 57,3%.', 'keywords': ['thống kê bão', 'áp thấp nhiệt đới', 'tỷ lệ 65%', 'Thanh Hóa', 'Huế', 'phân bố bão']}, {'id': 'TERRA_QA_084', 'source_document': 'a3515bb7de4f407c999b38eaad2be279.md', 'category': 'typhoon_flood', 'sub_category': 'Tổ hợp hình thế thời tiết cực đoan gây lũ lịch sử', 'difficulty': 'hard', 'question': 'Tác động tổ hợp của các hình thế thời tiết (bão/ATNĐ kết hợp không khí lạnh) đã gây ra các trận mưa lũ lịch sử điển hình nào tại miền Trung?', 'ground_truth_context': 'Chính tác động tổ hợp của các hình thế thời tiết này mới gây mưa lũ\nlớn lịch sử ở các triền sông. Bão Nancy chiều 22.IX.1979 đổ bộ vào Quảng\nTrị - Nam Quảng Bình gây mưa rất to: lưu vực sông Gianh mưa trên 700mm,\nKiến Giang - trên 1000mm; tại Vĩnh Linh - trên 800mm, Trường Sơn -\n1419mm, Kiến Giang - 1242mm; lũ sông Kiến Giang đạt mức lịch sử, vùng\nLệ Ninh ngập úng kéo dài 15-20 ngày. ATNĐ đổ bộ vào Phú Yên ngày\n29.X.1983 kết hợp với KKL gây mưa lớn từ Hà Tĩnh đến Khánh Hoà: mưa rất\nto ở Quảng Trị đến Quảng Nam; tại Huế, lượng mưa 3 ngày 30.X-1.XI là\n1217mm, gây lũ lụt lịch sử (đỉnh lũ là 5,85m kéo dài trong 11h) trên sông\nHương.', 'ground_truth_answer': 'Tác động tổ hợp của các hình thế thời tiết gây mưa lũ lớn lịch sử điển hình như: Bão Nancy chiều 22/9/1979 đổ bộ vào Quảng Trị - Nam Quảng Bình gây mưa rất to (lưu vực sông Gianh >700mm, Kiến Giang >1000mm, Trường Sơn 1419mm), lũ sông Kiến Giang đạt mức lịch sử và vùng Lệ Ninh ngập úng 15-20 ngày. Đợt ATNĐ đổ bộ Phú Yên ngày 29/10/1983 kết hợp không khí lạnh gây mưa lớn từ Hà Tĩnh đến Khánh Hoà, tại Huế mưa 3 ngày đạt 1217mm gây đỉnh lũ lịch sử 5,85m kéo dài suốt 11 giờ trên sông Hương.', 'keywords': ['tổ hợp thời tiết', 'không khí lạnh', 'bão Nancy', 'sông Gianh', 'sông Hương', 'lũ lịch sử']}, {'id': 'TERRA_QA_085', 'source_document': 'a3515bb7de4f407c999b38eaad2be279.md', 'category': 'typhoon_flood', 'sub_category': 'Hình thái thiên tai bão và ATNĐ đổ bộ liên tiếp', 'difficulty': 'medium', 'question': 'Những đặc điểm nguy hiểm điển hình của hiện tượng bão hoặc áp thấp nhiệt đới đổ bộ liên tiếp vào miền Trung là gì?', 'ground_truth_context': 'Bão hoặc bão và ATNĐ đổ bộ liên tiếp là loại thiên tai rất nguy hiểm:\n* Trong thời gian ngắn (8-15 ngày) có 2 - 3, thậm chí 4 cơn bão hoặc bão\nvà ATNĐ đổ bộ liên tiếp, có khi cùng vào một khu vực;\n* Bão hoặc ATNĐ vào thường có KKL tác động làm thiên tai càng nguy\nhiểm hơn;\n* Mưa thường rất to, cường độ rất lớn, diện mưa rộng, kéo dài nhiều ngày\n(7-15 ngày);\n* Lũ lụt nghiêm trọng trên nhiều triền sông, có khi xảy ra lũ lịch sử;\n* Thiệt hại về người và tài sản thường rất lớn.', 'ground_truth_answer': 'Bão hoặc bão và ATNĐ đổ bộ liên tiếp là loại thiên tai rất nguy hiểm với các đặc điểm: trong thời gian ngắn (8-15 ngày) có 2-3 thậm chí 4 cơn bão/ATNĐ đổ bộ liên tiếp (có khi vào cùng một khu vực); thường kết hợp với không khí lạnh làm thiên tai thêm nguy hiểm; mưa rất to cường độ lớn trên diện rộng kéo dài 7-15 ngày; gây lũ lụt nghiêm trọng hoặc lũ lịch sử trên nhiều triền sông; và gây thiệt hại rất lớn về người và tài sản.', 'keywords': ['bão liên tiếp', 'ATNĐ', 'không khí lạnh', 'mưa kéo dài', 'lũ lụt nghiêm trọng']}, {'id': 'TERRA_QA_086', 'source_document': 'a3515bb7de4f407c999b38eaad2be279.md', 'category': 'community_governance', 'sub_category': 'Giải pháp nâng cao năng lực quan trắc dự báo KTTV', 'difficulty': 'medium', 'question': 'Biện pháp cấp bách nào được kiến nghị hàng đầu để tăng cường mạng trạm quan trắc khí tượng thủy văn theo dõi bão, ATNĐ tại miền Trung?', 'ground_truth_context': '## 4. Biện pháp, giải pháp trước mắt và lâu dài tăng cường năng lực phục vụ KTTV\n\nTrên cơ sở đánh giá chung hiện trạng công tác KTTV ở miền Trung trong những năm qua, sau khi phân tích những đặc điểm địa lý tự nhiên; quy luật mưa, bão, lũ; những tồn tại trên mạng lưới trạm quan trắc (số lượng trạm, phân bố, loại thiệt bị đo, công nghệ và thiết bị lưu trữ, truyền tin,...); các công cụ và phương tiện cảnh báo, dự báo; cơ cấu tổ chức hiện hành cùng trình độ chuyên môn nghiệp vụ của đội ngũ cán bộ từ quan trắc viên đến dự báo viên, có thể kiến nghị một số biện pháp và giải pháp trước mắt và lâu dài nhằm tăng cường năng lực theo dõi, quan trắc cảnh báo và dự báo KTTV phục vụ phòng tránh thiên tai ở miền Trung như sau:\n\n1.  Tăng cường khẩn cấp mạng trạm theo dõi quan trắc bão, ATNĐ từ xa, từ trên cao và gần mặt đất, trước hết là các trạm tự động trên đảo, trạm phao, rada thời tiết quan sát trên vùng biển Đông (nơi hiện rất ít trạm) để phát hiện, theo dõi, dự báo chính xác hơn, sớm hơn tác động của bão, ATNĐ và các hiện tượng thời tiết nguy hiểm kèm theo. Xem xét việc bổ sung các trạm ở các vùng kinh tế mới, khu vực có các công trình trọng điểm.', 'ground_truth_answer': 'Kiến nghị tăng cường khẩn cấp mạng trạm theo dõi quan trắc bão, ATNĐ từ xa, từ trên cao và gần mặt đất, trước hết là các trạm tự động trên đảo, trạm phao, ra-đa thời tiết quan sát trên vùng biển Đông (nơi còn rất ít trạm) để phát hiện, theo dõi và dự báo chính xác hơn, sớm hơn tác động của bão, ATNĐ cùng các hiện tượng thời tiết nguy hiểm kèm theo; đồng thời xem xét bổ sung các trạm ở vùng kinh tế mới và khu vực có công trình trọng điểm.', 'keywords': ['quan trắc', 'dự báo KTTV', 'trạm tự động', 'trạm phao', 'rada thời tiết', 'biển Đông']}]
